create extension if not exists "pgcrypto";
create table public.toy_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,created_at timestamptz not null default now());
create table public.toy_invitations(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,slug text not null unique check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),partner_one text not null,partner_two text not null,event_date date not null,event_time time not null,venue text not null,address text not null default '',map_url text not null default '',message text not null default '',default_language text not null default 'uz' check(default_language in('uz','ru','en')),message_uz text,message_ru text,message_en text,created_by_email text,card_number text check(card_number is null or card_number~'^[0-9 ]{12,23}$'),card_holder text,theme jsonb not null default '{"accent":"#a4775a","style":"classic"}'::jsonb,theme_style text not null default 'classic' check(theme_style in('classic','garden','midnight')),cover_url text,gallery_urls text[] not null default '{}',music_url text,status text not null default 'draft' check(status in('draft','published','archived')),published_at timestamptz,expires_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.toy_guests(id uuid primary key default gen_random_uuid(),invitation_id uuid not null references public.toy_invitations(id) on delete cascade,name text not null,phone text,access_code text not null default encode(gen_random_bytes(8),'hex'),party_size integer not null default 1 check(party_size between 1 and 20),rsvp_status text not null default 'pending' check(rsvp_status in('pending','attending','declined')),attending_count integer check(attending_count between 0 and 20),note text,responded_at timestamptz,created_at timestamptz not null default now(),unique(invitation_id,access_code));
create table public.toy_site_settings(id text primary key check(id='creator_support'),creator_name text not null default 'Yaratuvchi',card_number text,updated_at timestamptz not null default now());
insert into public.toy_site_settings(id) values('creator_support');
alter table public.toy_profiles enable row level security; alter table public.toy_invitations enable row level security; alter table public.toy_guests enable row level security; alter table public.toy_site_settings enable row level security;
create policy toy_profiles_select on public.toy_profiles for select to authenticated using((select auth.uid())=id);
create policy toy_profiles_insert on public.toy_profiles for insert to authenticated with check((select auth.uid())=id);
create policy toy_profiles_update on public.toy_profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy toy_invitations_owner_admin on public.toy_invitations for all to authenticated using((select auth.uid())=owner_id or coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')='admin') with check((select auth.uid())=owner_id or coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')='admin');
create policy toy_invitations_public on public.toy_invitations for select to anon using(status='published' and deleted_at is null and event_date >= (now() at time zone 'Asia/Tashkent')::date-14);
create policy toy_guests_owner_admin on public.toy_guests for all to authenticated using(exists(select 1 from public.toy_invitations i where i.id=invitation_id and(i.owner_id=(select auth.uid()) or coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')='admin'))) with check(exists(select 1 from public.toy_invitations i where i.id=invitation_id and(i.owner_id=(select auth.uid()) or coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')='admin')));
create policy toy_settings_read on public.toy_site_settings for select to anon,authenticated using(true);
create policy toy_settings_admin_update on public.toy_site_settings for update to authenticated using(coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')='admin') with check(coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')='admin');
grant select on public.toy_invitations,public.toy_site_settings to anon; grant select,insert,update,delete on public.toy_profiles,public.toy_invitations,public.toy_guests to authenticated; grant select,update on public.toy_site_settings to authenticated;
create index toy_invitations_owner_idx on public.toy_invitations(owner_id); create index toy_invitations_deleted_idx on public.toy_invitations(deleted_at) where deleted_at is not null; create index toy_guests_invitation_idx on public.toy_guests(invitation_id);
create function public.toy_submit_rsvp(target_invitation uuid,guest_name text,response_status text,guest_count integer default 1,guest_note text default null) returns void language plpgsql security definer set search_path='' as $$ begin if length(btrim(guest_name)) not between 2 and 100 or response_status not in('attending','declined') or guest_count not between 1 and 10 or length(coalesce(guest_note,''))>500 then raise exception 'Invalid response details.'; end if; if not exists(select 1 from public.toy_invitations where id=target_invitation and status='published' and deleted_at is null and event_date >= (now() at time zone 'Asia/Tashkent')::date-14) then raise exception 'Invitation is unavailable.'; end if; insert into public.toy_guests(invitation_id,name,party_size,attending_count,rsvp_status,note,responded_at) values(target_invitation,btrim(guest_name),guest_count,case when response_status='attending' then guest_count else 0 end,response_status,nullif(btrim(guest_note),''),now()); end; $$;
revoke all on function public.toy_submit_rsvp(uuid,text,text,integer,text) from public; grant execute on function public.toy_submit_rsvp(uuid,text,text,integer,text) to anon,authenticated;
create function public.toy_cleanup_expired_invitations() returns integer language plpgsql security invoker set search_path='' as $$ declare removed integer; begin delete from public.toy_invitations where event_date < (now() at time zone 'Asia/Tashkent')::date-14; get diagnostics removed=row_count; return removed; end; $$;
revoke all on function public.toy_cleanup_expired_invitations() from public,anon; grant execute on function public.toy_cleanup_expired_invitations() to authenticated;
create function public.toy_permanently_delete_invitation(target_id uuid) returns void language plpgsql security invoker set search_path='' as $$ begin if coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')<>'admin' then raise exception 'Administrator access required'; end if; delete from public.toy_invitations where id=target_id and deleted_at is not null; end; $$;
revoke all on function public.toy_permanently_delete_invitation(uuid) from public,anon; grant execute on function public.toy_permanently_delete_invitation(uuid) to authenticated;
create function public.toy_enforce_owner_invitation_limit() returns trigger language plpgsql security invoker set search_path='' as $$ begin if coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')='admin' then return new; end if; perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(new.owner_id::text,0)); if exists(select 1 from public.toy_invitations where owner_id=new.owner_id and deleted_at is null) then raise exception 'Only one active invitation is allowed for this account.'; end if; return new; end; $$;
create trigger toy_owner_invitation_limit before insert on public.toy_invitations for each row execute function public.toy_enforce_owner_invitation_limit(); revoke all on function public.toy_enforce_owner_invitation_limit() from public,anon,authenticated;
create function public.toy_list_platform_accounts() returns table(user_id uuid,email text,full_name text,role text,registered_at timestamptz,last_sign_in_at timestamptz,invitation_count bigint,active_invitation_count bigint,deleted_invitation_count bigint,guest_response_count bigint) language plpgsql security definer set search_path='' as $$ begin if coalesce((select auth.jwt())->'app_metadata'->>'toy_role','')<>'admin' then raise exception 'Administrator access required'; end if; return query select u.id,u.email::text,p.full_name,coalesce(u.raw_app_meta_data->>'toy_role','user'),u.created_at,u.last_sign_in_at,count(distinct i.id),count(distinct i.id) filter(where i.deleted_at is null),count(distinct i.id) filter(where i.deleted_at is not null),count(g.id) from public.toy_profiles p join auth.users u on u.id=p.id left join public.toy_invitations i on i.owner_id=u.id left join public.toy_guests g on g.invitation_id=i.id group by u.id,u.email,p.full_name,u.raw_app_meta_data,u.created_at,u.last_sign_in_at order by u.created_at desc; end; $$;
revoke all on function public.toy_list_platform_accounts() from public,anon; grant execute on function public.toy_list_platform_accounts() to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('toy-wedding-media','toy-wedding-media',true,5242880,array['image/jpeg','image/png','image/webp','audio/mpeg','audio/mp4']);
create policy toy_media_insert on storage.objects for insert to authenticated with check(bucket_id='toy-wedding-media' and(storage.foldername(name))[1]=(select auth.uid())::text);
create policy toy_media_update on storage.objects for update to authenticated using(bucket_id='toy-wedding-media' and(storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='toy-wedding-media' and(storage.foldername(name))[1]=(select auth.uid())::text);
create policy toy_media_delete on storage.objects for delete to authenticated using(bucket_id='toy-wedding-media' and(storage.foldername(name))[1]=(select auth.uid())::text);
